CREATE TABLE IF NOT EXISTS stripe_checkout_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), generation int NOT NULL DEFAULT 1, idempotency_key text NOT NULL UNIQUE, session_id text UNIQUE, session_url text, status text NOT NULL CHECK(status IN ('CREATING','OPEN','COMPLETED','EXPIRED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(invoice_id,generation));
