DO $$ BEGIN ALTER TABLE payments ADD CONSTRAINT payment_provider_amount_shape CHECK((provider='LINDEN' AND amount_linden IS NOT NULL AND amount_minor IS NULL) OR (provider IN ('STRIPE','SIMULATION') AND amount_minor IS NOT NULL AND amount_linden IS NULL)); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
